style.css:
/* ChatGPT estilo Azul Clarito */
body, html {
    background-color: #cce7ff !important; /* Azul clarito */
    color: #002b4d !important; /* Texto en azul oscuro para contraste */
}

/* Cuadros y tarjetas */
div, section, article, main {
    background-color: #e6f3ff !important; /* Fondo más clarito */
    border-radius: 12px !important;
    border: 1px solid #99d0ff !important;
}

/* Botones */
button {
    background-color: #99d6ff !important;
    color: #002b4d !important;
    border: none !important;
    border-radius: 10px !important;
    transition: 0.3s;
}

button:hover {
    background-color: #66c2ff !important;
    color: white !important;
}

/* Inputs y cajas de texto */
textarea, input {
    background-color: #e6f3ff !important;
    color: #002b4d !important;
    border: 1px solid #99d0ff !important;
    border-radius: 10px !important;
}

/* Links */
a {
    color: #007acc !important;
}

a:hover {
    color: #005f99 !important;
    text-decoration: underline !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #cce7ff;
}

::-webkit-scrollbar-thumb {
    background: #66c2ff;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #3399ff;
}
